import {ensureMemory,SCENE_PRESETS,COMPLETION_MODES,ELEMENT_KINDS,applyPreset,commitScene,compileSceneConstraints} from './memory.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy=x=>JSON.parse(JSON.stringify(x));
const options=(items,value)=>items.map(([id,name])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(name)}</option>`).join('');
const labelKind=k=>ELEMENT_KINDS[k]||k;
const cameraPosition={south:[250,258,0],north:[250,42,180],east:[430,150,270],west:[70,150,90]};
function layoutSVG(scene,characters=[],selected='',mini=false){
  const [cx,cy,rotation]=cameraPosition[scene.camera]||cameraPosition.south;
  return `<svg class="${mini?'preset-map':'world-map'}" viewBox="0 0 500 300" role="${mini?'img':'group'}" aria-label="${esc(scene.name||'场景')}俯视布局，北在上方">
    <defs><pattern id="grid-${mini?'mini':'main'}-${esc(scene.id||'set')}" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M 25 0 L 0 0 0 25" fill="none" stroke="#b8a6e5" stroke-opacity=".09"/></pattern></defs>
    <rect x="25" y="20" width="450" height="260" rx="12" fill="#151720" stroke="#5e526e" stroke-width="1.5"/>
    <rect x="25" y="20" width="450" height="260" rx="12" fill="url(#grid-${mini?'mini':'main'}-${esc(scene.id||'set')})"/>
    ${!mini?'<text x="250" y="15" text-anchor="middle" class="map-compass">北 N</text><text x="491" y="155" text-anchor="middle" class="map-compass">东</text><text x="250" y="296" text-anchor="middle" class="map-compass">南 S</text><text x="9" y="155" text-anchor="middle" class="map-compass">西</text>':''}
    <g transform="translate(${cx} ${cy}) rotate(${rotation})"><path d="M0 0 L-65 -100 Q0 -123 65 -100 Z" fill="#a994e8" fill-opacity=".065" stroke="#ac97e1" stroke-opacity=".3" stroke-dasharray="4 5"/><rect x="-9" y="-6" width="18" height="12" rx="3" fill="#c5b2ee"/><path d="M-5 -9 L5 -9 L0 -15 Z" fill="#c5b2ee"/></g>
    ${scene.elements.filter(e=>e.enabled).map(e=>{const x=25+e.x*4.5,y=20+e.y*2.6;return `<g ${!mini?`role="button" tabindex="0" aria-label="编辑${esc(e.label)}的位置" data-memory-action="pick-object" data-object="${esc(e.id)}"`:''} class="map-object ${e.kind} ${selected===e.id?'is-selected':''}" transform="translate(${x} ${y})"><rect x="-36" y="-15" width="72" height="30" rx="${e.kind==='ambient'?15:6}"/><text text-anchor="middle" y="5">${esc(e.label.length>7?e.label.slice(0,6)+'…':e.label)}</text></g>`;}).join('')}
    ${!mini?scene.placements.map(p=>{const c=characters.find(c=>c.id===p.characterId);return c?`<g class="map-person" data-character="${esc(p.characterId)}" transform="translate(${25+p.x*4.5} ${20+p.y*2.6})"><circle r="16"/><text text-anchor="middle" y="5">${esc(c.name.slice(0,1))}</text><text class="person-name" text-anchor="middle" y="32">${esc(c.name)}</text></g>`:'';}).join(''):''}
    ${!mini&&!scene.elements.some(e=>e.enabled)?'<text x="250" y="139" text-anchor="middle" class="map-empty">你的场景，从这里开始</text><text x="250" y="164" text-anchor="middle" class="map-empty small">选择下方模板，或添加自己的物体</text>':''}
  </svg>`;
}
export class MemoryPanel {
  constructor({getRun,onChange,render,toast}){Object.assign(this,{getRun,onChange,rerender:render,toast});this.tab='scenes';this.drafts=new Map();this.sceneIds=new Map();this.selected='';this.details=new Set();}
  captureUI(){for(const name of ['character-positions','constraint-preview']){const el=document.querySelector(`.memory-workbench .${name}`);if(el){if(el.open)this.details.add(name);else this.details.delete(name);}}}
  draft(run){const m=ensureMemory(run);let id=this.sceneIds.get(run.id);if(!m.scenes.some(s=>s.id===id))id=m.scenes[0].id;this.sceneIds.set(run.id,id);const key=`${run.id}:${id}`;return this.drafts.get(key)||m.scenes.find(s=>s.id===id);}
  edit(){const run=this.getRun(),draft=copy(this.draft(run));this.drafts.set(`${run.id}:${draft.id}`,draft);return draft;}
  updateDraftStatus(){const bar=document.querySelector('.memory-savebar');if(!bar)return;bar.querySelector('strong').textContent='有尚未应用的修改';bar.querySelector('span').textContent='保存后将重新生成分镜及其下游产物。';for(const b of bar.querySelectorAll('button'))b.disabled=false;const pre=document.querySelector('.constraint-preview pre');if(pre){const r=copy(this.getRun()),d=this.draft(r);r.memory.scenes=r.memory.scenes.map(s=>s.id===d.id?d:s);pre.textContent=compileSceneConstraints(r,d.id);}}
  render(run){
    const m=ensureMemory(run),scene=this.draft(run),dirty=this.drafts.has(`${run.id}:${scene.id}`),busy=run.status==='running';
    const enabled=m.scenes.reduce((n,s)=>n+s.elements.filter(e=>e.enabled).length,0);
    return `<div class="memory-workbench">
      <div class="memory-intro"><div><span class="memory-eyebrow">STORY WORLD · 项目记忆</span><h2>让每个镜头，记得同一个世界。</h2><p>把角色、空间与场景细节变成可检查的创作设定。</p></div><span class="memory-version">记忆 v${m.revision}<small>设定已保存在本机</small></span></div>
      <div class="memory-metrics">${[[m.scenes.length,'场景空间','同一场景持续复用'],[m.characters.length,'角色设定','外观与声线'],[enabled,'已选场景元素','剧情、背景与氛围'],[m.history.length,'设定变更','来源与版本可追溯']].map(([n,l,d])=>`<div><strong>${n}</strong><span>${l}</span><small>${d}</small></div>`).join('')}</div>
      <div class="memory-tabs" role="tablist" aria-label="项目记忆类型">${[['scenes','场景与空间'],['characters','角色与风格'],['timeline','事实与时间线']].map(([id,name])=>`<button role="tab" aria-selected="${this.tab===id}" class="${this.tab===id?'active':''}" data-memory-action="tab" data-tab="${id}">${name}</button>`).join('')}</div>
      ${this.tab==='scenes'?this.sceneView(run,scene,dirty,busy):this.tab==='characters'?this.characterView(run,busy):this.timelineView(run)}
    </div>`;
  }
  sceneView(run,s,dirty,busy){
    const m=run.memory,selected=s.elements.find(e=>e.id===this.selected)||s.elements.find(e=>e.enabled),disabled=busy?'disabled':'';
    const previewRun=copy(run);previewRun.memory.scenes=previewRun.memory.scenes.map(x=>x.id===s.id?s:x);
    return `<div class="memory-scene-toolbar"><label for="memory-scene">当前场景<select id="memory-scene" ${disabled}>${m.scenes.map((x,i)=>`<option value="${esc(x.id)}" ${s.id===x.id?'selected':''}>场景 ${i+1} · ${esc(x.name)}</option>`).join('')}</select></label><span class="scene-revision">场景 v${s.revision} · ${s.source==='user'?'用户确认':s.source==='sample'?'预制示例':'剧本导入'}</span></div>
    <div class="world-grid"><section class="memory-panel layout-panel"><div class="memory-panel-title"><div><h3>空间布局</h3><p>俯视示意 · 点击物体可调整位置</p></div><span class="memory-tag">世界坐标</span></div>
      ${layoutSVG(s,m.characters,selected?.id)}<div class="map-legend"><span class="required">剧情必需</span><span class="persistent">固定背景</span><span class="ambient">氛围细节</span><span class="person">角色</span></div>
      <label class="memory-field">场景基准机位<select data-memory-field="camera" ${disabled}>${options([['south','南侧 · 向北拍摄'],['north','北侧 · 向南拍摄'],['east','东侧 · 向西拍摄'],['west','西侧 · 向东拍摄']],s.camera)}</select></label>
      ${selected?`<div class="position-editor"><strong>${esc(selected.label)}的位置</strong><div><label>东西位置 <input type="range" min="8" max="92" value="${selected.x}" data-memory-coordinate="x" data-object="${esc(selected.id)}" aria-label="${esc(selected.label)}东西位置" ${disabled}><output>${selected.x}</output></label><label>南北位置 <input type="range" min="8" max="92" value="${selected.y}" data-memory-coordinate="y" data-object="${esc(selected.id)}" aria-label="${esc(selected.label)}南北位置" ${disabled}><output>${selected.y}</output></label></div></div>`:''}
      <p class="memory-help">机位变化会改变画面左右，不会改变场景中物体的位置。此图为创作布局示意。</p>
    </section>
    <section class="memory-panel"><div class="memory-panel-title"><div><h3>环境与连续性</h3><p>明确这一场的开始、结束与不变项</p></div></div><label class="memory-field">天气<select data-memory-field="weather" ${disabled}>${options([...new Set(['未指定','晴','阴','雨','雪','雾','无',s.weather])].map(x=>[x,x]),s.weather)}</select></label><label class="memory-field">光线<input data-memory-field="lighting" value="${esc(s.lighting)}" maxlength="180" ${disabled}></label>
      <label class="memory-field">起始状态<textarea data-memory-field="startState" placeholder="例如：旧伞放在柜台上，店主站在柜台后。" maxlength="800" ${disabled}>${esc(s.startState)}</textarea></label>
      <label class="memory-field">结束状态<textarea data-memory-field="endState" placeholder="例如：女孩接过旧伞，店主仍留在柜台后。" maxlength="800" ${disabled}>${esc(s.endState)}</textarea></label>
      <label class="memory-field">场景参考图 <span class="memory-help">可选 · JPG / PNG / WebP，500 KB 以内</span><input type="file" id="memory-reference" accept="image/png,image/jpeg,image/webp" ${disabled}></label>${s.reference?`<div class="scene-reference"><img src="${s.reference}" alt="当前场景参考图"><button class="btn sm" data-memory-action="remove-reference" ${disabled}>移除参考图</button></div>`:''}
      <span class="memory-unverified">创作设定 · 待生成画面验证</span>
    </section></div>
    <section class="memory-panel completion-panel"><div class="memory-panel-title"><div><span class="memory-eyebrow">SCENE COMPLETION</span><h3>把背景，也纳入创作。</h3><p>选一个起点，再决定哪些细节出现在你的世界里。</p></div><span class="memory-tag">显式选择</span></div>
      <p class="memory-help">模板只提供可编辑的建议。切换模板会替换草稿中的场景元素，保存后才会用于生成。</p><div class="preset-grid">${SCENE_PRESETS.map(p=>`<button class="preset-card ${s.preset===p.id?'selected':''}" data-memory-action="preset" data-preset="${p.id}" aria-pressed="${s.preset===p.id}" ${disabled}>${layoutSVG({...s,id:p.id,name:p.name,elements:p.elements},[], '',true)}<strong>${p.name}</strong><span>${p.description}</span>${s.preset===p.id?'<b aria-hidden="true">✓</b>':''}</button>`).join('')}</div>
      <fieldset class="completion-modes" ${disabled}><legend>背景补全方式</legend>${COMPLETION_MODES.map(mode=>`<label class="${s.mode===mode.id?'selected':''}"><input type="radio" name="completion-mode" value="${mode.id}" ${s.mode===mode.id?'checked':''}><span><strong>${mode.name}</strong><small>${mode.description}</small></span></label>`).join('')}</fieldset>
      <div class="memory-panel-title"><h4>场景元素 <span class="muted">${s.elements.filter(e=>e.enabled).length} / ${s.elements.length} 已选</span></h4><button class="btn sm" data-memory-action="add-object" ${disabled}>＋ 添加元素</button></div>
      <p class="memory-help">取消勾选会关闭对应的背景补全，不会删除剧本中已经明确需要的对象。</p><div class="element-list">${s.elements.length?s.elements.map(e=>`<div class="element-row ${e.enabled?'enabled':''}"><label class="element-toggle"><input type="checkbox" data-memory-element="${esc(e.id)}" ${e.enabled?'checked':''} ${disabled}><span>${esc(e.label)}</span></label><select data-memory-kind="${esc(e.id)}" aria-label="${esc(e.label)}的用途" ${disabled}>${options(Object.entries(ELEMENT_KINDS),e.kind)}</select><button class="element-position" data-memory-action="pick-object" data-object="${esc(e.id)}" ${disabled}>位置 ${e.x}, ${e.y}</button><button class="iconbtn" data-memory-action="delete-object" data-object="${esc(e.id)}" aria-label="删除${esc(e.label)}" ${disabled}>×</button></div>`).join(''):'<div class="memory-empty-inline">尚未添加背景元素。选择模板后，可逐项勾选；也可以直接添加。</div>'}</div>
      <div class="custom-element" hidden><label for="new-object">新元素名称</label><input id="new-object" placeholder="例如：墙上的旧挂钟" maxlength="40"><button class="btn sm" data-memory-action="confirm-object">添加</button></div>
      <details class="character-positions" ${this.details.has('character-positions')?'open':''}><summary>角色站位 <span>${s.placements.length} 位已设置</span></summary>${m.characters.length?m.characters.map((c,i)=>{const p=s.placements.find(p=>p.characterId===c.id);return `<div class="placement-row"><label><input type="checkbox" data-memory-character="${esc(c.id)}" ${p?'checked':''} ${disabled}>${esc(c.name)}</label>${p?`<label>东西<input type="number" min="8" max="92" value="${p.x}" data-placement="${esc(c.id)}" data-axis="x" ${disabled}></label><label>南北<input type="number" min="8" max="92" value="${p.y}" data-placement="${esc(c.id)}" data-axis="y" ${disabled}></label>`:''}</div>`;}).join(''):'<p class="memory-help">生成剧本后，可在此设置角色站位。</p>'}</details>
      <label class="memory-field">其他连续性要求<textarea data-memory-field="notes" placeholder="例如：保留同一套货架布局；背景不出现参与剧情的新人物。" maxlength="1200" ${disabled}>${esc(s.notes)}</textarea></label>
      <details class="constraint-preview" ${this.details.has('constraint-preview')?'open':''}><summary>查看将传给生成模型的场景约束</summary><pre>${esc(compileSceneConstraints(previewRun,s.id))}</pre><p>这些约束会加入每个相关镜头的提示词。场景参考图通过视频接口传入；布局图本身不作为三维控制信号。</p></details>
    </section>
    <div class="memory-savebar"><div><strong>${dirty?'有尚未应用的修改':'当前设定已保存'}</strong><span>${dirty?'保存后将重新生成分镜及其下游产物。':'下一次分镜与视频生成会读取这些设定。'}</span></div><div><button class="btn" data-memory-action="discard" ${!dirty||busy?'disabled':''}>放弃修改</button><button class="btn primary" data-memory-action="save" ${!dirty||busy?'disabled':''}>保存并用于生成</button></div></div>`;
  }
  characterView(run,busy){const m=run.memory;return `<div class="memory-character-grid">${m.characters.map((c,i)=>`<section class="memory-panel character-editor"><div class="character-identity"><span class="character-token">${esc(c.name.slice(0,1))}</span><div><h3>${esc(c.name)}</h3><span>${esc(c.id)} · ${c.source==='user'?'用户设定':'剧本设定'}</span></div></div><label class="memory-field">固定外观与服装<textarea id="character-description-${i}" maxlength="1500" ${busy?'disabled':''}>${esc(c.description)}</textarea></label><label class="memory-field">声线设定<input id="character-voice-${i}" value="${esc(c.voice)}" maxlength="300" ${busy?'disabled':''}></label><button class="btn sm" data-memory-action="save-character" data-index="${i}" ${busy?'disabled':''}>保存角色设定</button></section>`).join('')||'<div class="memory-panel memory-empty-inline">生成剧本后，角色将自动出现在这里。你可以继续编辑并固定外观与声线。</div>'}</div><section class="memory-panel"><h3>全局视觉风格</h3><label class="memory-field"><span>所有镜头共同遵循的风格</span><input id="memory-style" value="${esc(m.style)}" maxlength="300" ${busy?'disabled':''}></label><button class="btn" data-memory-action="save-style" ${busy?'disabled':''}>保存视觉风格</button><p class="memory-help">声线描述作为创作设定保存；当前配音仍使用服务中配置的统一音色。</p></section>`;}
  timelineView(run){const m=run.memory;return `<section class="memory-panel"><div class="memory-panel-title"><div><h3>故事事实与状态变化</h3><p>剧情要求与画面观测分别保存，生成偏差不会自动成为故事事实。</p></div><span class="memory-tag">待画面验证</span></div><div class="memory-timeline">${m.scenes.map((s,i)=>`<article><span class="timeline-node">${i+1}</span><div><h4>${esc(s.name)}</h4><p>${esc(run.artifacts.script?.scenes.find(x=>x.id===s.id)?.beat||'等待剧本生成')}</p><div class="state-transition"><div><small>起始状态</small><span>${esc(s.startState||'尚未指定')}</span></div><div><small>结束状态</small><span>${esc(s.endState||'尚未指定')}</span></div></div><span class="memory-unverified">场景 v${s.revision} · ${s.source==='user'?'用户确认设定':'剧本／示例设定'}</span></div></article>`).join('')}</div></section><section class="memory-panel"><h3>故事事实</h3>${m.facts.map(f=>`<p class="memory-fact">${esc(f)}</p>`).join('')||'<p class="memory-help">等待编剧产物。</p>'}</section><section class="memory-panel"><h3>设定变更记录</h3>${m.history.slice(-12).reverse().map(h=>`<div class="memory-history"><span>${esc(new Date(h.time).toLocaleString('zh-CN'))}</span><p>${esc(h.summary)}</p><small>${esc(h.source==='user'?'用户编辑':'剧本导入')} · v${h.revision}</small></div>`).join('')||'<p class="memory-help">保存角色或场景设定后，会在这里记录来源与版本。</p>'}<details class="memory-history-details"><summary>工作流阶段摘要 · ${m.summaries.length}</summary>${m.summaries.map(s=>`<p class="memory-fact">${esc(s.node)} · ${esc(s.summary)}</p>`).join('')}</details></section>`;}
  click(event){
    const button=event.target.closest('[data-memory-action]');if(!button||button.disabled)return false;
    const action=button.dataset.memoryAction,run=this.getRun();
    if(action==='tab'){this.tab=button.dataset.tab;this.rerender();return true;}
    if(run.status==='running'){this.toast('请先停止当前任务，再编辑设定');return true;}
    if(action==='pick-object'){this.selected=button.dataset.object;this.rerender();return true;}
    if(action==='preset'){const draft=this.edit(),next=applyPreset(draft,button.dataset.preset);this.drafts.set(`${run.id}:${draft.id}`,next);this.selected=next.elements[0]?.id||'';this.rerender();}
    if(action==='delete-object'){const d=this.edit();d.elements=d.elements.filter(e=>e.id!==button.dataset.object);this.rerender();}
    if(action==='add-object'){const row=document.querySelector('.custom-element');row.hidden=false;row.querySelector('input').focus();}
    if(action==='confirm-object'){const input=document.querySelector('#new-object'),name=input.value.trim();if(!name){this.toast('请填写元素名称');return true;}const d=this.edit();if(d.elements.length>=30){this.toast('每个场景最多 30 个元素');return true;}d.elements.push({id:`object-${globalThis.crypto.randomUUID()}`,label:name,kind:'persistent',x:50,y:50,enabled:true});this.rerender();}
    if(action==='remove-reference'){this.edit().reference='';this.rerender();}
    if(action==='discard'){const d=this.draft(run);this.drafts.delete(`${run.id}:${d.id}`);this.rerender();}
    if(action==='save'){try{const d=this.draft(run);commitScene(run,d);this.drafts.delete(`${run.id}:${d.id}`);this.onChange('场景设定已保存，后续生成将读取你的选择');}catch(e){this.toast(e.message);}}
    if(action==='save-character'){const index=Number(button.dataset.index),c=run.memory.characters[index],description=document.querySelector(`#character-description-${index}`).value.trim();if(!description){this.toast('请填写角色外观');return true;}c.description=description;c.voice=document.querySelector(`#character-voice-${index}`).value.trim();c.source='user';run.memory.revision++;run.memory.history.push({time:new Date().toISOString(),source:'user',revision:run.memory.revision,summary:`更新角色设定：${c.name}`});this.onChange('角色设定已保存');}
    if(action==='save-style'){const style=document.querySelector('#memory-style').value.trim();if(!style){this.toast('请填写视觉风格');return true;}run.memory.style=style;run.memory.revision++;run.memory.history.push({time:new Date().toISOString(),source:'user',revision:run.memory.revision,summary:'更新全局视觉风格'});this.onChange('视觉风格已保存');}
    return true;
  }
  async change(event){
    const el=event.target;if(this.getRun().status==='running')return;
    if(el.id==='memory-scene'){this.sceneIds.set(this.getRun().id,el.value);this.selected='';this.rerender();return;}
    if(el.id==='memory-reference'){const file=el.files[0];if(!file)return;if(file.size>500*1024||!['image/png','image/jpeg','image/webp'].includes(file.type)){this.toast('请选择 500 KB 以内的 JPG、PNG 或 WebP 图片');return;}const runId=this.getRun().id,sceneId=this.draft(this.getRun()).id;const reference=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('无法读取参考图'));reader.readAsDataURL(file);}).catch(e=>{this.toast(e.message);return '';});if(!reference||this.getRun().id!==runId||this.draft(this.getRun()).id!==sceneId||this.getRun().status==='running')return;this.edit().reference=reference;this.rerender();return;}
    if(el.dataset.memoryField){this.edit()[el.dataset.memoryField]=el.value;if(el.tagName==='SELECT')this.rerender();else this.updateDraftStatus();return;}
    if(el.name==='completion-mode'){this.edit().mode=el.value;this.rerender();return;}
    if(el.dataset.memoryElement){const e=this.edit().elements.find(x=>x.id===el.dataset.memoryElement);if(e)e.enabled=el.checked;this.rerender();return;}
    if(el.dataset.memoryKind){const e=this.edit().elements.find(x=>x.id===el.dataset.memoryKind);if(e)e.kind=el.value;this.rerender();return;}
    if(el.dataset.memoryCoordinate){const e=this.edit().elements.find(x=>x.id===el.dataset.object);if(e)e[el.dataset.memoryCoordinate]=Number(el.value);this.rerender();return;}
    if(el.dataset.memoryCharacter){const d=this.edit();d.placements=d.placements.filter(p=>p.characterId!==el.dataset.memoryCharacter);if(el.checked)d.placements.push({characterId:el.dataset.memoryCharacter,x:50,y:65});this.rerender();return;}
    if(el.dataset.placement){const p=this.edit().placements.find(p=>p.characterId===el.dataset.placement);if(p)p[el.dataset.axis]=Math.min(92,Math.max(8,Number(el.value)||50));this.updateDraftStatus();}
  }
  input(event){const el=event.target;if(this.getRun().status==='running')return;
    if(el.dataset.memoryField){this.edit()[el.dataset.memoryField]=el.value;this.updateDraftStatus();}
    if(el.dataset.placement){const p=this.edit().placements.find(p=>p.characterId===el.dataset.placement);if(p){p[el.dataset.axis]=Math.min(92,Math.max(8,Number(el.value)||50));const group=document.querySelector(`.world-map [data-character="${CSS.escape(p.characterId)}"]`);group?.setAttribute('transform',`translate(${25+p.x*4.5} ${20+p.y*2.6})`);this.updateDraftStatus();}}
    if(el.dataset.memoryCoordinate){const e=this.edit().elements.find(x=>x.id===el.dataset.object);if(e){e[el.dataset.memoryCoordinate]=Number(el.value);const group=document.querySelector(`.world-map [data-object="${CSS.escape(e.id)}"]`);group?.setAttribute('transform',`translate(${25+e.x*4.5} ${20+e.y*2.6})`);el.nextElementSibling.value=el.value;this.updateDraftStatus();}}
  }
}
